        protected bool ParseInput()
        {
            Prefix = Request["prefix"];
            var count = Request["count"];
            var startIndex = Request["start"];
            if (string.IsNullOrWhiteSpace(Prefix) || string.IsNullOrWhiteSpace(count) || string.IsNullOrWhiteSpace(startIndex))
            {
                Message = "Please input prefix and member count";
                return false;
            }

            if (!int.TryParse(count, out MemberCount) || MemberCount > 5000)
            {
                Message = "Invalid member count. Member count should be between 1 and 5000";
                return false;
            }

            if (!int.TryParse(startIndex, out StartIndex))
            {
                Message = "Invalid Start index. Start index should be a number";
                return false;
            }

            return true;
        }

